import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Cooking","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/cooking.md","filePath":"guide/professions/cooking.md"}'),t={name:"guide/professions/cooking.md"};function r(s,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Permalink to &quot;Cooking&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/cooking.html">full design specification</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Cooking is intended as hands-on work at a real station: a Cooking gump represents a campfire setup, kitchen, stove, oven or grill. Ingredients begin cooking when placed into its work areas; different foods have different preparation windows. Timing and assembly matter.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Food should support satiation, nutrition, recovery, stamina efficiency, fatigue, temperature resistance and situational survival. It should not become a collection of potion-like stat buffs. Camping can provide a wilderness cooking stand, while fuel connects with Lumberjacking.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>A Culinary Journal gathers recipes and food knowledge from cultures, cooks, books, exploration and experimentation. A personal Taste Codex could reveal preferences through eating instead of showing every favorite at character creation. Favorite dishes may offer greater comfort or satisfaction. Broad culinary knowledge can remain an endgame pursuit.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p>Low skill should allow useful simple meals; higher skill widens tolerances and improves control without replacing execution. <a href="/Syrolands-Public/guide/professions/overview.html">Shared learning and batching</a> apply. <a href="/Syrolands-Public/guide/professions/lumberjacking.html">Lumberjacking</a> supplies fuel knowledge; exact nutrition, tastes and recovery effects remain open.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/game-design/professions/cooking.html">Full design specification</a></p>',11)])])}const f=a(t,[["render",r]]);export{p as __pageData,f as default};
